#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

const PATCH = 'pfotentechnik-research-import-replacement-1.1.0';
const TARGET_NAME = 'research-import.json';
const PAYLOAD_BASE64 = '';

function fail(message) {
  throw new Error(`[${PATCH}] ${message}`);
}

function probeRepoRoot(startDir) {
  let current = path.resolve(startDir);
  while (true) {
    const packageJson = path.join(current, 'package.json');
    const appDir = path.join(current, 'apps', 'pfotentechnik');
    if (fs.existsSync(packageJson) && fs.existsSync(appDir)) return current;
    const parent = path.dirname(current);
    if (parent === current) return null;
    current = parent;
  }
}

function findRepoRoot(...candidates) {
  for (const candidate of candidates) {
    const found = probeRepoRoot(candidate);
    if (found) return found;
  }
  fail('Repository-Root nicht gefunden. Lege den Installer unter /3 ab oder starte ihn innerhalb von Yushamon/affiliate-template.');
}

function validateResearchImport(rawText, label) {
  let parsed;
  try {
    parsed = JSON.parse(rawText);
  } catch (error) {
    fail(`${label} ist kein valides JSON: ${error.message}`);
  }

  if (parsed.version !== 2) fail(`${label}: version muss 2 sein.`);
  if (parsed.provider !== 'manual-chatgpt') fail(`${label}: provider muss manual-chatgpt sein.`);
  if (!Array.isArray(parsed.scope) || parsed.scope.length === 0) fail(`${label}: scope fehlt oder ist leer.`);
  if (!Array.isArray(parsed.items) || parsed.items.length === 0) fail(`${label}: items fehlt oder ist leer.`);

  const ids = new Set();
  const allowedTypes = new Set(['topic', 'product', 'manufacturer', 'content-refresh']);
  const allowedStatus = new Set(['open']);
  const allowedEffort = new Set(['small', 'medium', 'large']);
  const allowedImpact = new Set(['low', 'medium', 'high']);

  for (const [index, item] of parsed.items.entries()) {
    const prefix = `${label}: items[${index}]`;
    if (!item || typeof item !== 'object' || Array.isArray(item)) fail(`${prefix} muss ein Objekt sein.`);
    if (typeof item.id !== 'string' || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(item.id)) fail(`${prefix}.id ist ungültig.`);
    if (ids.has(item.id)) fail(`${label}: doppelte id ${item.id}.`);
    ids.add(item.id);

    if (!allowedTypes.has(item.type)) fail(`${prefix}.type ist ungültig.`);
    if (!allowedStatus.has(item.status)) fail(`${prefix}.status ist ungültig.`);

    for (const key of ['priority', 'confidence']) {
      if (!Number.isInteger(item[key]) || item[key] < 0 || item[key] > 100) {
        fail(`${prefix}.${key} muss 0..100 sein.`);
      }
    }

    if (!item.repositoryMatch || typeof item.repositoryMatch !== 'object') fail(`${prefix}.repositoryMatch fehlt.`);
    if (!item.opportunity || typeof item.opportunity !== 'object') fail(`${prefix}.opportunity fehlt.`);

    for (const key of ['seo', 'ux', 'business', 'freshness', 'priority']) {
      const value = item.opportunity[key];
      if (!Number.isInteger(value) || value < 0 || value > 100) {
        fail(`${prefix}.opportunity.${key} muss 0..100 sein.`);
      }
    }

    if (!allowedEffort.has(item.opportunity.effort)) fail(`${prefix}.opportunity.effort ist ungültig.`);
    if (item.impact?.estimatedSeoImpact && !allowedImpact.has(item.impact.estimatedSeoImpact)) {
      fail(`${prefix}.impact.estimatedSeoImpact ist ungültig.`);
    }

    if (!item.implementationBrief || typeof item.implementationBrief !== 'object') {
      fail(`${prefix}.implementationBrief fehlt.`);
    }
    if (!Array.isArray(item.implementationBrief.acceptanceCriteria) || item.implementationBrief.acceptanceCriteria.length === 0) {
      fail(`${prefix}.implementationBrief.acceptanceCriteria fehlt oder ist leer.`);
    }
    if (!Array.isArray(item.implementationBrief.verification) || item.implementationBrief.verification.length === 0) {
      fail(`${prefix}.implementationBrief.verification fehlt oder ist leer.`);
    }

    if (!item.visualBrief || typeof item.visualBrief !== 'object' || !Array.isArray(item.visualBrief.motifs)) {
      fail(`${prefix}.visualBrief ist unvollständig.`);
    }

    if (!Array.isArray(item.actions) || item.actions.length === 0) {
      fail(`${prefix}.actions fehlt oder ist leer.`);
    }
    if (!Array.isArray(item.evidence) || item.evidence.length === 0) {
      fail(`${prefix}.evidence fehlt oder ist leer.`);
    }
  }

  return parsed;
}

function sameBytes(a, b) {
  return a.length === b.length && Buffer.compare(a, b) === 0;
}

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = findRepoRoot(process.cwd(), scriptDir);
const target = path.join(repoRoot, TARGET_NAME);
const payload = Buffer.from(PAYLOAD_BASE64, 'base64');
const payloadText = payload.toString('utf8');
const parsed = validateResearchImport(payloadText, 'eingebetteter Research-Import');

let changed = true;
let backupPath = null;

if (fs.existsSync(target)) {
  const existing = fs.readFileSync(target);
  if (sameBytes(existing, payload)) {
    changed = false;
  } else {
    const backupDir = path.join(repoRoot, '3', 'backups', PATCH);
    fs.mkdirSync(backupDir, { recursive: true });
    backupPath = path.join(backupDir, `${TARGET_NAME}.bak`);
    fs.copyFileSync(target, backupPath);
  }
}

if (changed) {
  const tmp = `${target}.${process.pid}.tmp`;
  fs.writeFileSync(tmp, payload);
  fs.renameSync(tmp, target);
}

const written = fs.readFileSync(target, 'utf8');
const writtenParsed = validateResearchImport(written, 'geschriebene research-import.json');

if (writtenParsed.updatedAt !== parsed.updatedAt) {
  fail('Ergebnisvalidierung fehlgeschlagen: updatedAt weicht vom eingebetteten Payload ab.');
}
if (writtenParsed.items.length !== parsed.items.length) {
  fail('Ergebnisvalidierung fehlgeschlagen: Finding-Anzahl abweichend.');
}

const expectedIds = parsed.items.map((item) => item.id);
const writtenIds = writtenParsed.items.map((item) => item.id);
if (JSON.stringify(expectedIds) !== JSON.stringify(writtenIds)) {
  fail('Ergebnisvalidierung fehlgeschlagen: Finding-IDs oder Reihenfolge abweichend.');
}

console.log(`[${PATCH}] ${changed ? 'Ersetzt' : 'Unverändert'}: ${path.relative(repoRoot, target)}`);
console.log(`[${PATCH}] Findings: ${writtenParsed.items.length}`);
console.log(`[${PATCH}] Scope: ${writtenParsed.scope.join(', ')}`);
if (backupPath) console.log(`[${PATCH}] Backup: ${path.relative(repoRoot, backupPath)}`);
console.log(`[${PATCH}] Nächster Schritt: npm --workspace apps/pfotentechnik run research:import -- ./research-import.json`);
console.log(`[${PATCH}] Danach: npm --workspace apps/pfotentechnik run research:check`);
